fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();

    // Handle empty input early
    if n == 0 {
        return Vec::new();
    }

    // Preallocate vector with exact capacity to avoid reallocations
    let mut res = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        res.push(num);
        // Insert delimiter after every element except the last
        if i < n - 1 {
            res.push(delim);
        }
    }

    res
}